import{z as A,x as B,o as E,c as g,q as l,j as i,D as e,d as s,s as o,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"测试图形与 gauge","description":"","frontmatter":{"title":"测试图形与 gauge","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/test-patterns-gauges.md","filePath":"litho/test-patterns-gauges.md","lastUpdated":1791063341000}'),d={name:"litho/test-patterns-gauges.md"};function p(u,a,D,h,m,c){const r=B("Mermaid");return E(),g("div",null,[a[2]||(a[2]=l('<h1 id="测试图形与-gauge" tabindex="-1">测试图形与 gauge <a class="header-anchor" href="#测试图形与-gauge" aria-label="Permalink to &quot;测试图形与 gauge&quot;">​</a></h1><div class="epigraph"><p>模型只在被量过的几何上受约束；gauge 的抽样偏差会变成全芯片的系统性盲目。</p><footer>—— 对照 OPC 校准 gauge、通过节距与二维测试键的产线通称</footer></div><p><a href="/litho/resist-model-calibration">上一课</a>把拟合协议钉死。缺口是样本从哪来：只放 1D 通过节距，二维线端与 SRAM 会成为外推。本课钉测试图形与 gauge。残差怎么读，留给<a href="/litho/model-residual-analysis">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>校准集是实验设计。典型缺失：只有水平和垂直、没有 45°；只有线没有孔；只有标称剂量没有窗口角；只有逻辑密度没有 SRAM densest pitch；助条宽度未扫。SEM 收缩、量测部位（顶/底）、抽样数决定噪声地板——比噪声更密的模型项是假精度。</p><p>缺口是<strong>可观测性</strong>，不是再列 CM 参数名。把产品热区当唯一 gauge，会在 TAPOUT 前才发现模型从未见过那种邻域。</p><p><span class="marginnote">术语翻译：gauge 就是给模型「考试」用的标准图形样本——一组尺寸和形状都设计好的光刻测试图形（不同节距、线端、孔阵等），先量出它们曝光后的真实 CD，再让模型去预测；预测不准就调模型参数，直到考卷全过。</span></p><h3 id="gauge-必须进同一条计量链" tabindex="-1">Gauge 必须进同一条计量链 <a class="header-anchor" href="#gauge-必须进同一条计量链" aria-label="Permalink to &quot;Gauge 必须进同一条计量链&quot;">​</a></h3><p>CD-SEM 配方、收缩补偿、OCD 模型，要与将来监控一致。换 SEM 配方等于换数据集。计量课的 <a href="/litho/cd-sem-shrink">CD-SEM shrink</a> 在这里是校准偏差源。</p><p><span class="marginnote">故意放「禁戒节距」和「设计不允许但 OPC 可能长出的助条」进 gauge，才能约束病态区。只放 DRC 合法图形，模型在 MRC 边界上自由游荡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：通过节距、iso-dense、线端缩短、二维拐角、孔阵列、助条存在/缺失、FEM。统计：每类足够重复以估 SEM 噪声。权重：按产品重要性，而不是按好测。EUV 加随机：同一 gauge 多点平均，避免把泊松噪声拟合进确定性核。</p><p><span class="marginnote">数字实例：CD-SEM 单次测量的随机噪声约 1 nm 量级。同一图形平均 \\(N\\) 次，噪声降为 \\(1/\\sqrt{N}\\)：测 16 遍降到四分之一。每类图形的重复数要按这个道理留够，否则你拟合的是量测噪声，不是物理。</span></p>',13)),(E(),i(n,null,{default:e(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22gauge%20%E8%A6%81%E6%92%91%E5%BC%80%E7%9A%84%E5%87%A0%E4%BD%95%E8%BD%B4%22%5D%20--%3E%20O%5B%22%E5%8F%96%E5%90%91%3A%200%20%2F%2090%20%2F%2045%20%E5%BA%A6%22%5D%0A%20%20G%20--%3E%20D%5B%22%E4%B8%80%E7%BB%B4%E9%95%BF%E7%BA%BF%20vs%20%E4%BA%8C%E7%BB%B4%E7%BA%BF%E7%AB%AF%E6%8B%90%E8%A7%92%22%5D%0A%20%20G%20--%3E%20P%5B%22%E8%8A%82%E8%B7%9D%3A%20%E9%80%9A%E8%BF%87%E8%8A%82%E8%B7%9D%E5%8A%A0%E7%A6%81%E6%88%92%E8%8A%82%E8%B7%9D%22%5D%0A%20%20G%20--%3E%20H%5B%22%E7%BA%BF%20%2F%20%E5%AD%94%20%2F%20%E5%8A%A9%E6%9D%A1%E6%9C%89%E6%97%A0%22%5D%0A%20%20G%20--%3E%20W%5B%22%E5%89%82%E9%87%8F%E4%B8%8E%E7%84%A6%E8%B7%9D%E7%AA%97%E5%8F%A3%E8%A7%92%20FEM%22%5D%0A%20%20O%20--%3E%20B%5B%22%E7%BC%BA%E5%93%AA%E6%A0%B9%E8%BD%B4%20%E6%A8%A1%E5%9E%8B%E5%B0%B1%E5%9C%A8%E5%93%AA%E4%B8%AA%E6%96%B9%E5%90%91%E7%9B%B2%22%5D%0A%20%20D%20--%3E%20B%0A%20%20P%20--%3E%20B%0A%20%20H%20--%3E%20B%0A%20%20W%20--%3E%20B%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"与 DTCO：库里真实 clips 应占保持集，不只占宣传图。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"成像算子对某些几何方向不敏感（信息论上不可观），对应参数会与别的项交换。gauge 的作用是打开这些方向的激励。若所有 gauge 都是长线，阈值与光学半径会混叠——残差课会看到「什么都能吃一点、什么都吃不干净」。",-1)),(E(),i(n,null,{default:e(()=>[o(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROD%5B%22%E4%BA%A7%E5%93%81%E5%85%B3%E9%94%AE%E5%87%A0%E4%BD%95%22%5D%20--%3E%20G%5B%22gauge%20%E7%9F%A9%E9%98%B5%22%5D%0A%20%20PHYS%5B%22%E9%80%9A%E8%BF%87%E8%8A%82%E8%B7%9D%20%2F%20FEM%20%2F%202D%22%5D%20--%3E%20G%0A%20%20G%20--%3E%20MET%5B%22SEM%20%2F%20OCD%20%E9%85%8D%E6%96%B9%22%5D%0A%20%20MET%20--%3E%20FIT%5B%22%E6%A0%A1%E5%87%86%20%2B%20%E4%BF%9D%E6%8C%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Gauge 晶圆不是产品良率证明。测太多会变成计量瓶颈，延迟模型版本。不把某代工厂的测试键版图当公开标准。</p><p><span class="marginnote">常见误区：初学者容易以为 gauge 图形「越多越好、越大越全越好」。实际上图形总数受计量时间约束，测太多反而拖慢模型迭代；关键是覆盖方向（上图的五根轴）和按产品重要性分配权重，不是无脑堆数量。</span></p><p>后课默认：校准数据有设计好的激励；下一课用残差图判断缺的是光学、胶还是抽样。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Gauge 是实验设计；抽样偏差等于模型盲区。</li><li>计量配方与 SEM 收缩是数据集的一部分。</li><li>保持集要含真实库 clips 与病态节距。</li><li>出处：OPC 校准 gauge 产线通称；计量与模型绑定的公开讨论。</li></ul>',6))])}const _=A(d,[["render",p]]);export{C as __pageData,_ as default};
